#compdef delva
# zsh completion for delva — generated by `delva completion zsh`
_delva() {
  local -a candidates
  local cmdpath="" word
  local -i skip=0
  for word in "${(@)words[2,CURRENT-1]}"; do
    if (( skip )); then skip=0; continue; fi
    case "$word" in
      --store|-s|--width|--key|-k|--path|-p|--line-width|--max-levels|--mode|--nested|--type|-t|--limit|-n|--order|--after|--max-bytes|--where|--normalization|--fragment-size|--index-key|--exclude-key|--min-indexed-string|--max-indexed-string|--document-key|--replace|--ignore-key|--ignore-path|--max-differences) skip=1 ;;
      -*) ;;
      *) cmdpath="${cmdpath:+$cmdpath }$word" ;;
    esac
  done
  case "${words[CURRENT-1]}" in
    --mode) candidates=('document' 'element'); _describe 'value' candidates; return ;;
    --nested) candidates=('all' 'outermost'); _describe 'value' candidates; return ;;
    --order) candidates=('asc' 'desc'); _describe 'value' candidates; return ;;
    --normalization) candidates=('none' 'nfc'); _describe 'value' candidates; return ;;
    --store|-s|--width|--key|-k|--path|-p|--line-width|--max-levels|--type|-t|--limit|-n|--after|--max-bytes|--where|--fragment-size|--index-key|--exclude-key|--min-indexed-string|--max-indexed-string|--document-key|--replace|--ignore-key|--ignore-path|--max-differences) _files; return ;;
  esac
  case "$cmdpath" in
    "") candidates=('info:Show what a store holds and how it was created' 'get:Print a stored document, or the nodes a JSONPath query selects from it' 'search:Search every document' 'explain:Show how a JSONPath search would find its documents, without running it' 'path:Print where a node is in its document, as a Normalized Path' 'types:Inspect the types assigned to objects' 'init:Create a store; what it is created with is fixed for its life' 'insert:Insert JSON documents, each file one document, and print their ids' 'delete:Delete documents; asks first at a terminal, and needs --force without one' 'reset:Delete every document and type, leaving the store as init created it; asks first at a terminal' 'verify:Read the whole store and report any damage, changing nothing; exits 1 when there is some' 'compare:Compare two JSON values, stored or not; exits 0 when equal and 1 when not' 'completion:Print a shell completion script to stdout' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "info") candidates=('--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "get") candidates=('--key:The document with this key, in a store created with --document-key' '--path:Only the nodes this JSONPath query selects, one per line' '--exit-status:Exit 1 when nothing was found' '--pretty:Indent the JSON (the default at a terminal)' '--compact:Write the JSON on one line (the default down a pipe)' '--line-width:Columns an indented container may take on one line; 0 breaks every one; implies --pretty' '--max-levels:Write containers nested deeper than n as {...} and [...]; implies --pretty' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "search") candidates=('kv:Find the objects with a member equal to a value' 'path:Find the nodes a JSONPath query selects, in every document' 'key:List documents in the order of their keys, in a store created with --document-key' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "search kv") candidates=('--string:Take the value as a string, not as JSON' '--mode:Hits are whole documents, or the objects that contain the match' '--nested:Keep hits inside other hits, or only the outermost' '--type:Only objects of this type' '--limit:At most n results; a notice says how to get the rest' '--order:Oldest documents first, or newest' '--after:Resume after this cursor, from a hit'\''s JSON or a '\''more\:'\'' notice' '--max-bytes:End a page before its hits pass this size, such as 16MiB' '--count:Print how many hits there are, not the hits; with --limit, count at most n' '--exit-status:Exit 1 when nothing was found' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "search path") candidates=('--scan:Read every document when no index term narrows the query' '--where:Only the documents whose root passes this filter, such as "@.kind == '\''order'\''"' '--mode:Hits are whole documents, or the objects that contain the match' '--nested:Keep hits inside other hits, or only the outermost' '--type:Only objects of this type' '--limit:At most n results; a notice says how to get the rest' '--order:Oldest documents first, or newest' '--after:Resume after this cursor, from a hit'\''s JSON or a '\''more\:'\'' notice' '--max-bytes:End a page before its hits pass this size, such as 16MiB' '--count:Print how many hits there are, not the hits; with --limit, count at most n' '--exit-status:Exit 1 when nothing was found' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "search key") candidates=('--limit:At most n results; a notice says how to get the rest' '--order:Smallest key first, or largest' '--after:Resume after this cursor, from a hit'\''s JSON or a '\''more\:'\'' notice' '--max-bytes:End a page before its hits pass this size, such as 16MiB' '--count:Print how many hits there are, not the hits; with --limit, count at most n' '--exit-status:Exit 1 when nothing was found' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "explain") candidates=('--where:Only the documents whose root passes this filter, such as "@.kind == '\''order'\''"' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "path") candidates=('--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "types") candidates=('list:List the types and about how many objects each has' 'count:Count the objects of a type exactly' 'objects:List the objects of a type, as doc\:node' 'assign:Give an object a type, replacing the one it had' 'clear:Take an object'\''s type away' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "types list") candidates=('--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "types count") candidates=('--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "types objects") candidates=('--after:Resume after this object, as doc\:node' '--limit:At most n results; a notice says how to get the rest' '--exit-status:Exit 1 when nothing was found' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "types assign") candidates=('--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "types clear") candidates=('--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "init") candidates=('--normalization:Normalize every string and key to NFC as it is read' '--fragment-size:Target size of the fragments documents are split into' '--no-hash-terms:Don'\''t index whole objects and arrays; searches for object or array values then fail' '--index-key:Index only members with this key; repeat for more' '--exclude-key:Never index members with this key; repeat for more' '--min-indexed-string:Index only string values of at least n bytes' '--max-indexed-string:Index only string values of at most n bytes' '--document-key:The JSONPath of the string that names each document; no two documents then share one' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "insert") candidates=('--type:Give the objects a path names a type, as <jsonpath>=<Type>; repeat for more' '--replace:Delete this document in the same change, if it still exists (one file only); repeat for more' '--upsert:Replace the document that has the same key, in the same change (a store created with --document-key)' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "delete") candidates=('--dry-run:Show which documents would be deleted, and delete nothing' '--force:Don'\''t ask for confirmation' '--no-input:Never prompt' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "reset") candidates=('--force:Don'\''t ask for confirmation' '--no-input:Never prompt' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "verify") candidates=('--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "compare") candidates=('--diff:List the differences, not just whether there are any' '--ignore-key:Leave out members with this key, at any depth' '--ignore-path:Leave out the value at this path, such as $.updatedAt' '--types:Objects differ when their assigned types do' '--max-differences:Stop after n differences' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
    "completion") candidates=('bash' 'zsh' 'fish' 'powershell' '--store:The store directory' '--json:Machine-readable output on stdout' '--verbose:More detail on stderr' '--quiet:Nothing on stderr but errors' '--no-color:Never emit colour' '--width:Columns to fit output to') ;;
  esac
  _describe 'command' candidates
}
compdef _delva delva
